// A function whose return type might change during refactoring.
// For example, from a simple string to a more complex object.
#include <string>
#include <vector>

std::string getResourceID() { return "ID-12345"; }

// 1. Correctness: Avoids type mismatches and potential data loss.
std::vector<int> v;
auto sz = v.size(); // sz is correctly std::vector<int>::size_type, not a plain int.

// 2. Maintainability: Eases refactoring.
// If getResourceID's return type changes, this line adapts automatically.
auto id = getResourceID();

// 3. Efficiency: Avoids performance penalties from implicit conversions.
// With an explicit type, a temporary might be created and copied.
// With auto, 'id' is initialized directly with the return value.
